sys_script_include.script:
// TestReach — ATF Coverage Analyzer & Test Gap Detector
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0
//
// TestReachCoverageEngine — Static coverage analysis engine.
// Builds dependency graph from ATF test definitions, computes coverage
// percentages per artifact and per table, manages incremental snapshots.
// @class TestReachCoverageEngine @namespace x_snc_testreach

var TestReachCoverageEngine = Class.create();
TestReachCoverageEngine.prototype = {

    /**
     * Full static coverage analysis for all artifacts in a scope.
     * Parses sys_atf_test + sys_atf_step, builds dependency graph,
     * computes coverage % per artifact.
     *
     * @param {string} appScope - Scope prefix (e.g., "x_hr_core")
     * @returns {object} {coverage_map: {}, stats: {total, tested, untested, coverage_pct}}
     */
    analyzeAll: function(appScope) {
        var depGraph = this.buildDependencyGraph(appScope);
        var artifactList = this._getArtifactList(appScope);
        var coverage = this.computeCoverage(depGraph, artifactList);

        var total = artifactList.length;
        var tested = 0;
        for (var i = 0; i < coverage.length; i++) {
            if (coverage[i].tested_by_count > 0) {
                tested++;
            }
        }
        var untested = total - tested;
        var coveragePct = total > 0 ? parseFloat(((tested / total) * 100).toFixed(2)) : 0;

        return {
            coverage_map: coverage,
            stats: {
                total: total,
                tested: tested,
                untested: untested,
                coverage_pct: coveragePct
            }
        };
    },

    /**
     * Single-artifact coverage check. Used by the in-form smart suggestion banner.
     *
     * @param {string} artifactSysId - Sys ID of the artifact
     * @param {string} artifactType - Type: business_rule, script_include, etc.
     * @returns {object} {tested_by: [], coverage_pct: 0}
     */
    analyzeArtifact: function(artifactSysId, artifactType) {
        var testedBy = [];
        var stepGr = new GlideRecord('sys_atf_step');
        stepGr.addQuery('active', true);
        stepGr.query();

        while (stepGr.next()) {
            var config = stepGr.getValue('config') || '';
            if (config.indexOf(artifactSysId) !== -1) {
                var testGr = new GlideRecord('sys_atf_test');
                if (testGr.get(stepGr.getValue('test'))) {
                    testedBy.push({
                        test_sys_id: testGr.getUniqueValue(),
                        test_name: testGr.getValue('name') || ''
                    });
                }
            }
        }

        return {
            tested_by: testedBy,
            coverage_pct: testedBy.length > 0 ? 100 : 0
        };
    },

    /**
     * Builds a map of artifact_sys_id → [test_sys_ids] by parsing ATF step config XML.
     *
     * @param {string} appScope - Scope prefix
     * @returns {object} {artifact_sys_id: [test_sys_id, ...]}
     */
    buildDependencyGraph: function(appScope) {
        var graph = {};

        var testGr = new GlideRecord('sys_atf_test');
        testGr.addQuery('active', true);
        testGr.query();

        while (testGr.next()) {
            var testSysId = testGr.getUniqueValue();
            var stepGr = new GlideRecord('sys_atf_step');
            stepGr.addQuery('test', testSysId);
            stepGr.addQuery('active', true);
            stepGr.query();

            while (stepGr.next()) {
                var config = stepGr.getValue('config') || '';
                var refIds = this._extractSysIds(config);
                for (var i = 0; i < refIds.length; i++) {
                    var refId = refIds[i];
                    if (!graph[refId]) {
                        graph[refId] = [];
                    }
                    if (graph[refId].indexOf(testSysId) === -1) {
                        graph[refId].push(testSysId);
                    }
                }
            }
        }

        return graph;
    },

    /**
     * Computes coverage % from the dependency graph.
     *
     * @param {object} depGraph - {artifact_sys_id: [test_sys_ids]}
     * @param {array} artifactList - [{sys_id, name, type, table_name, app_scope}]
     * @returns {array} [{artifact_sys_id, artifact_name, artifact_type, artifact_table, app_scope, tested_by_count, coverage_pct}]
     */
    computeCoverage: function(depGraph, artifactList) {
        var results = [];
        for (var i = 0; i < artifactList.length; i++) {
            var artifact = artifactList[i];
            var testIds = depGraph[artifact.sys_id] || [];
            var testedByCount = testIds.length;
            results.push({
                artifact_sys_id: artifact.sys_id,
                artifact_name: artifact.name,
                artifact_type: artifact.type,
                artifact_table: artifact.table_name || '',
                app_scope: artifact.app_scope || '',
                tested_by_count: testedByCount,
                coverage_pct: testedByCount > 0 ? 100 : 0
            });
        }
        return results;
    },

    /**
     * Runs full analysis, writes results to x_snc_testreach_coverage_snapshot,
     * returns snapshot ID.
     *
     * @param {string} appScope - Scope prefix
     * @returns {string} snapshotSysId — sys_id of the trend snapshot record
     */
    snapshotCoverage: function(appScope) {
        var result = this.analyzeAll(appScope);
        var now = new GlideDateTime();
        var snapshotTs = now.getValue();
        var snapshotSysId = '';

        // Write per-artifact coverage records
        for (var i = 0; i < result.coverage_map.length; i++) {
            var item = result.coverage_map[i];
            var snapGr = new GlideRecord('x_snc_testreach_coverage_snapshot');
            snapGr.initialize();
            snapGr.setValue('artifact_sys_id', item.artifact_sys_id);
            snapGr.setValue('artifact_type', item.artifact_type);
            snapGr.setValue('artifact_name', item.artifact_name);
            snapGr.setValue('artifact_table', item.artifact_table);
            snapGr.setValue('app_scope', item.app_scope);
            snapGr.setValue('tested_by_count', item.tested_by_count);
            snapGr.setValue('coverage_pct', item.coverage_pct);
            snapGr.setValue('snapshot_type', 'coverage');
            snapGr.setValue('snapshot_ts', snapshotTs);
            snapGr.setValue('criticality', this._computeCriticality(item.artifact_sys_id, item.artifact_type));

            var findings = {
                test_ids: (result.coverage_map[i].tested_by_count > 0) ? ['see_dependency_graph'] : [],
                test_names: [],
                last_modified: snapshotTs
            };
            snapGr.setValue('findings_json', JSON.stringify(findings));
            snapGr.setValue('skeleton_json', JSON.stringify({generated: false, test_sys_id: null, steps: [], ai_generated: false}));

            try {
                var insertedSysId = snapGr.insert();
                if (i === 0) {
                    snapshotSysId = insertedSysId;
                }
            } catch (e) {
                gs.error('TestReachCoverageEngine.snapshotCoverage: insert failed for ' + item.artifact_sys_id + ': ' + e.message);
            }
        }

        // Write zero-coverage gap records
        for (var j = 0; j < result.coverage_map.length; j++) {
            var gapItem = result.coverage_map[j];
            if (gapItem.tested_by_count === 0) {
                var gapGr = new GlideRecord('x_snc_testreach_coverage_snapshot');
                gapGr.initialize();
                gapGr.setValue('artifact_sys_id', gapItem.artifact_sys_id);
                gapGr.setValue('artifact_type', gapItem.artifact_type);
                gapGr.setValue('artifact_name', gapItem.artifact_name);
                gapGr.setValue('artifact_table', gapItem.artifact_table);
                gapGr.setValue('app_scope', gapItem.app_scope);
                gapGr.setValue('tested_by_count', 0);
                gapGr.setValue('coverage_pct', 0);
                gapGr.setValue('snapshot_type', 'gap');
                gapGr.setValue('snapshot_ts', snapshotTs);
                gapGr.setValue('criticality', this._computeCriticality(gapItem.artifact_sys_id, gapItem.artifact_type));
                gapGr.setValue('findings_json', JSON.stringify({test_ids: [], test_names: [], last_modified: snapshotTs}));
                gapGr.setValue('skeleton_json', JSON.stringify({generated: false, test_sys_id: null, steps: [], ai_generated: false}));
                try {
                    gapGr.insert();
                } catch (e) {
                    gs.error('TestReachCoverageEngine.snapshotCoverage: gap insert failed for ' + gapItem.artifact_sys_id + ': ' + e.message);
                }
            }
        }

        return snapshotSysId;
    },

    /**
     * Reads trend snapshots and returns time-series data.
     *
     * @param {string} appScope - Scope prefix
     * @param {number} weeks - Number of weeks to return (default 12)
     * @returns {array} [{week: "2026-W27", pct: 63.5}, ...]
     */
    getCoverageTrend: function(appScope, weeks) {
        weeks = weeks || 12;
        var trend = [];
        var trendGr = new GlideRecord('x_snc_testreach_coverage_snapshot');
        trendGr.addQuery('app_scope', appScope);
        trendGr.addQuery('snapshot_type', 'trend');
        trendGr.orderByDesc('snapshot_ts');
        trendGr.setLimit(weeks);
        trendGr.query();

        while (trendGr.next()) {
            var trendJson = trendGr.getValue('trend_json') || '{}';
            try {
                var parsed = JSON.parse(trendJson);
                if (parsed.weekly_snapshots) {
                    for (var i = 0; i < parsed.weekly_snapshots.length; i++) {
                        trend.push(parsed.weekly_snapshots[i]);
                    }
                }
            } catch (e) {
                gs.warn('TestReachCoverageEngine.getCoverageTrend: JSON parse failed for ' + trendGr.getUniqueValue());
            }
        }

        return trend;
    },

    /**
     * Collects all custom artifacts in a scope from OOTB tables.
     *
     * @param {string} appScope - Scope prefix
     * @returns {array} [{sys_id, name, type, table_name, app_scope}]
     * @private
     */
    _getArtifactList: function(appScope) {
        var artifacts = [];

        // Business Rules (sys_script)
        var brGr = new GlideRecord('sys_script');
        brGr.addQuery('sys_scope', appScope);
        brGr.addQuery('active', true);
        brGr.query();
        while (brGr.next()) {
            artifacts.push({
                sys_id: brGr.getUniqueValue(),
                name: brGr.getValue('name') || '',
                type: 'business_rule',
                table_name: brGr.getValue('collection') || '',
                app_scope: appScope
            });
        }

        // Script Includes (sys_script_include)
        var siGr = new GlideRecord('sys_script_include');
        siGr.addQuery('sys_scope', appScope);
        siGr.addQuery('active', true);
        siGr.query();
        while (siGr.next()) {
            artifacts.push({
                sys_id: siGr.getUniqueValue(),
                name: siGr.getValue('name') || '',
                type: 'script_include',
                table_name: '',
                app_scope: appScope
            });
        }

        // Client Scripts (sys_ui_script)
        var csGr = new GlideRecord('sys_ui_script');
        csGr.addQuery('sys_scope', appScope);
        csGr.addQuery('active', true);
        csGr.query();
        while (csGr.next()) {
            artifacts.push({
                sys_id: csGr.getUniqueValue(),
                name: csGr.getValue('name') || '',
                type: 'client_script',
                table_name: csGr.getValue('table') || '',
                app_scope: appScope
            });
        }

        // UI Actions (sys_ui_action)
        var uaGr = new GlideRecord('sys_ui_action');
        uaGr.addQuery('sys_scope', appScope);
        uaGr.addQuery('active', true);
        uaGr.query();
        while (uaGr.next()) {
            artifacts.push({
                sys_id: uaGr.getUniqueValue(),
                name: uaGr.getValue('name') || '',
                type: 'ui_action',
                table_name: uaGr.getValue('table') || '',
                app_scope: appScope
            });
        }

        // UI Policies (sys_ui_policy)
        var upGr = new GlideRecord('sys_ui_policy');
        upGr.addQuery('sys_scope', appScope);
        upGr.addQuery('active', true);
        upGr.query();
        while (upGr.next()) {
            artifacts.push({
                sys_id: upGr.getUniqueValue(),
                name: upGr.getValue('short_description') || '',
                type: 'ui_policy',
                table_name: upGr.getValue('table') || '',
                app_scope: appScope
            });
        }

        // Flows (sys_hub_flow)
        var flowGr = new GlideRecord('sys_hub_flow');
        flowGr.addQuery('sys_scope', appScope);
        flowGr.addQuery('active', true);
        flowGr.query();
        while (flowGr.next()) {
            artifacts.push({
                sys_id: flowGr.getUniqueValue(),
                name: flowGr.getValue('name') || '',
                type: 'flow',
                table_name: '',
                app_scope: appScope
            });
        }

        // ACL Rules (sys_security_acl)
        var aclGr = new GlideRecord('sys_security_acl');
        aclGr.addQuery('sys_scope', appScope);
        aclGr.addQuery('active', true);
        aclGr.query();
        while (aclGr.next()) {
            artifacts.push({
                sys_id: aclGr.getUniqueValue(),
                name: aclGr.getValue('name') || '',
                type: 'acl',
                table_name: aclGr.getValue('name') || '',
                app_scope: appScope
            });
        }

        // Transform Maps (sys_transform_map)
        var tmGr = new GlideRecord('sys_transform_map');
        tmGr.addQuery('sys_scope', appScope);
        tmGr.addQuery('active', true);
        tmGr.query();
        while (tmGr.next()) {
            artifacts.push({
                sys_id: tmGr.getUniqueValue(),
                name: tmGr.getValue('name') || '',
                type: 'transform_map',
                table_name: tmGr.getValue('source_table') || '',
                app_scope: appScope
            });
        }

        return artifacts;
    },

    /**
     * Extracts sys_ids from ATF step config XML.
     *
     * @param {string} configXml - ATF step config XML string
     * @returns {array} Array of sys_id strings
     * @private
     */
    _extractSysIds: function(configXml) {
        var ids = [];
        if (!configXml) {
            return ids;
        }
        var xmlDoc = new XMLDocument(configXml);
        var nodes = xmlDoc.getElementsByTagName('sys_id');
        for (var i = 0; i < nodes.getLength(); i++) {
            var idVal = nodes.item(i).getTextContent();
            if (idVal && idVal.length === 32) {
                ids.push(idVal);
            }
        }
        return ids;
    },

    /**
     * Computes criticality score (1-5) for an artifact.
     * Base 1 + production flag (2) + downstream dependency count (1 per 5 deps, max 2).
     *
     * @param {string} artifactSysId - Sys ID of the artifact
     * @param {string} artifactType - Type of artifact
     * @returns {number} Criticality score 1-5
     * @private
     */
    _computeCriticality: function(artifactSysId, artifactType) {
        var criticality = 1;

        // Check if artifact is in a production scope (simplified: active + not in dev scope)
        // In a real deployment, this would check sys_scope.is_production or similar flags
        var scopeGr = new GlideRecord('sys_scope');
        if (scopeGr.get('scope', artifactType === 'business_rule' ? 'global' : '')) {
            // Production-like scope detection
        }

        // Count downstream dependencies via sys_audit references
        var auditGr = new GlideRecord('sys_audit');
        auditGr.addQuery('documentkey', artifactSysId);
        auditGr.setLimit(25);
        auditGr.query();
        var depCount = auditGr.getRowCount();
        var depBonus = Math.min(2, Math.floor(depCount / 5));
        criticality += depBonus;

        return Math.min(5, criticality);
    },

    type: 'TestReachCoverageEngine'
};

// TestReach — ATF Coverage Analyzer & Test Gap Detector
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0
//
// TestReachRiskEngine — Risk scoring, upgrade gap analysis, test skeleton generation,
// CI/CD gate checks, and dashboard data aggregation.
// @class TestReachRiskEngine @namespace x_snc_testreach

var TestReachRiskEngine = Class.create();
TestReachRiskEngine.prototype = {

    /**
     * Computes composite risk score from coverage data + criticality weights.
     *
     * @param {string} appScope - Scope prefix (e.g., "x_hr_core")
     * @param {string} upgradeTarget - Target release (e.g., "xanadu")
     * @returns {object} {risk_score: 0-100, details: {untested_count, low_coverage_count, total_artifacts, coverage_pct, top_risks: [], recommendation: ""}}
     */
    computeRiskScore: function(appScope, upgradeTarget) {
        var snapGr = new GlideRecord('x_snc_testreach_coverage_snapshot');
        snapGr.addQuery('app_scope', appScope);
        snapGr.addQuery('snapshot_type', 'coverage');
        snapGr.query();

        var untestedCount = 0;
        var lowCoverageCount = 0;
        var totalArtifacts = 0;
        var totalCriticality = 0;
        var topRisks = [];

        while (snapGr.next()) {
            totalArtifacts++;
            var coveragePct = parseFloat(snapGr.getValue('coverage_pct') || 0);
            var criticality = parseInt(snapGr.getValue('criticality') || 1, 10);
            totalCriticality += criticality;

            if (coveragePct === 0) {
                untestedCount++;
                topRisks.push({
                    name: snapGr.getValue('artifact_name') || '',
                    type: snapGr.getValue('artifact_type') || '',
                    criticality: criticality
                });
            } else if (coveragePct < 50) {
                lowCoverageCount++;
            }
        }

        // Sort top risks by criticality descending, take top 10
        topRisks.sort(function(a, b) { return b.criticality - a.criticality; });
        topRisks = topRisks.slice(0, 10);

        var criticalityAvg = totalArtifacts > 0 ? (totalCriticality / totalArtifacts) : 1;
        var riskScore = Math.min(100, Math.round((untestedCount * criticalityAvg * 10) + (lowCoverageCount * 5)));

        var testedCount = totalArtifacts - untestedCount;
        var coveragePctAgg = totalArtifacts > 0 ? parseFloat(((testedCount / totalArtifacts) * 100).toFixed(2)) : 0;

        var details = {
            untested_count: untestedCount,
            low_coverage_count: lowCoverageCount,
            total_artifacts: totalArtifacts,
            coverage_pct: coveragePctAgg,
            top_risks: topRisks,
            recommendation: this._generateRecommendation(riskScore, untestedCount, appScope)
        };

        // Persist risk score
        var riskGr = new GlideRecord('x_snc_testreach_risk_score');
        riskGr.addQuery('app_scope', appScope);
        riskGr.addQuery('upgrade_target', upgradeTarget);
        riskGr.query();
        if (riskGr.next()) {
            riskGr.setValue('risk_score', riskScore);
            riskGr.setValue('untested_count', untestedCount);
            riskGr.setValue('low_coverage_count', lowCoverageCount);
            riskGr.setValue('total_artifacts', totalArtifacts);
            riskGr.setValue('coverage_pct', coveragePctAgg);
            riskGr.setValue('details_json', JSON.stringify(details));
            riskGr.setValue('computed_ts', new GlideDateTime().getValue());
            riskGr.setValue('threshold_pass', riskScore <= 50);
            try {
                riskGr.update();
            } catch (e) {
                gs.error('TestReachRiskEngine.computeRiskScore: update failed: ' + e.message);
            }
        } else {
            riskGr.initialize();
            riskGr.setValue('app_scope', appScope);
            riskGr.setValue('app_name', this._getAppName(appScope));
            riskGr.setValue('upgrade_target', upgradeTarget);
            riskGr.setValue('risk_score', riskScore);
            riskGr.setValue('untested_count', untestedCount);
            riskGr.setValue('low_coverage_count', lowCoverageCount);
            riskGr.setValue('total_artifacts', totalArtifacts);
            riskGr.setValue('coverage_pct', coveragePctAgg);
            riskGr.setValue('details_json', JSON.stringify(details));
            riskGr.setValue('computed_ts', new GlideDateTime().getValue());
            riskGr.setValue('threshold_pass', riskScore <= 50);
            try {
                riskGr.insert();
            } catch (e) {
                gs.error('TestReachRiskEngine.computeRiskScore: insert failed: ' + e.message);
            }
        }

        return {
            risk_score: riskScore,
            details: details
        };
    },

    /**
     * Cross-references Upgrade Preview skipped records with coverage data.
     *
     * @param {string} upgradeTarget - Target release (e.g., "xanadu")
     * @returns {array} [{artifact_name, artifact_type, app_scope, risk_level, skipped, coverage_pct}]
     */
    generateUpgradeGapReport: function(upgradeTarget) {
        var gaps = [];

        // Query upgrade history log for skipped records
        var upgradeGr = new GlideRecord('sys_upgrade_history_log');
        upgradeGr.addQuery('state', 'skipped');
        upgradeGr.orderByDesc('sys_created_on');
        upgradeGr.setLimit(500);
        upgradeGr.query();

        while (upgradeGr.next()) {
            var recordType = upgradeGr.getValue('record_type') || '';
            var recordSysId = upgradeGr.getValue('record_sys_id') || '';

            // Check if this skipped record has coverage data
            var snapGr = new GlideRecord('x_snc_testreach_coverage_snapshot');
            snapGr.addQuery('artifact_sys_id', recordSysId);
            snapGr.addQuery('snapshot_type', 'coverage');
            snapGr.query();

            if (snapGr.next()) {
                var coveragePct = parseFloat(snapGr.getValue('coverage_pct') || 0);
                var riskLevel = 'low';
                if (coveragePct === 0) {
                    riskLevel = 'critical';
                } else if (coveragePct < 50) {
                    riskLevel = 'high';
                } else if (coveragePct < 100) {
                    riskLevel = 'medium';
                }

                gaps.push({
                    artifact_name: snapGr.getValue('artifact_name') || recordType,
                    artifact_type: snapGr.getValue('artifact_type') || recordType,
                    app_scope: snapGr.getValue('app_scope') || '',
                    risk_level: riskLevel,
                    skipped: true,
                    coverage_pct: coveragePct,
                    record_type: recordType,
                    record_sys_id: recordSysId
                });
            } else {
                // Skipped record not in our coverage data — unknown risk
                gaps.push({
                    artifact_name: recordType,
                    artifact_type: recordType,
                    app_scope: '',
                    risk_level: 'unknown',
                    skipped: true,
                    coverage_pct: -1,
                    record_type: recordType,
                    record_sys_id: recordSysId
                });
            }
        }

        return gaps;
    },

    /**
     * Creates stub ATF test records for an untested artifact.
     * Uses GenAI Controller for step descriptions when available.
     *
     * @param {string} artifactSysId - Sys ID of the artifact
     * @param {string} artifactType - Type: business_rule, script_include, etc.
     * @returns {object} {test_sys_id: "", steps: [{order, description, config}]}
     */
    generateTestSkeleton: function(artifactSysId, artifactType) {
        var steps = [];
        var testSysId = '';

        // Get artifact details
        var artifactName = '';
        var artifactTable = '';
        var artifactScript = '';

        if (artifactType === 'business_rule') {
            var brGr = new GlideRecord('sys_script');
            if (brGr.get(artifactSysId)) {
                artifactName = brGr.getValue('name') || '';
                artifactTable = brGr.getValue('collection') || '';
                artifactScript = brGr.getValue('script') || '';
            }
        } else if (artifactType === 'script_include') {
            var siGr = new GlideRecord('sys_script_include');
            if (siGr.get(artifactSysId)) {
                artifactName = siGr.getValue('name') || '';
                artifactScript = siGr.getValue('script') || '';
            }
        }

        // Generate step descriptions using GenAI Controller if available
        var stepDescriptions = this._generateStepDescriptions(artifactName, artifactType, artifactScript);

        // Create the ATF test record
        var testGr = new GlideRecord('sys_atf_test');
        testGr.initialize();
        testGr.setValue('name', '[TestReach] Test stub for: ' + artifactName);
        testGr.setValue('description', 'Auto-generated test skeleton for ' + artifactType + ' "' + artifactName + '". Review and customize before use.');
        testGr.setValue('sys_scope', 'x_snc_testreach');
        testGr.setValue('active', true);
        try {
            testSysId = testGr.insert();
        } catch (e) {
            gs.error('TestReachRiskEngine.generateTestSkeleton: test insert failed: ' + e.message);
            return { test_sys_id: '', steps: [] };
        }

        // Create ATF step records
        for (var i = 0; i < stepDescriptions.length; i++) {
            var stepGr = new GlideRecord('sys_atf_step');
            stepGr.initialize();
            stepGr.setValue('test', testSysId);
            stepGr.setValue('name', stepDescriptions[i].name);
            stepGr.setValue('description', stepDescriptions[i].description);
            stepGr.setValue('order', i + 1);
            stepGr.setValue('sys_scope', 'x_snc_testreach');
            stepGr.setValue('active', true);

            var configXml = this._buildStepConfig(artifactType, artifactTable, stepDescriptions[i]);
            stepGr.setValue('config', configXml);

            try {
                var stepSysId = stepGr.insert();
                steps.push({
                    order: i + 1,
                    description: stepDescriptions[i].description,
                    config: configXml,
                    step_sys_id: stepSysId
                });
            } catch (e) {
                gs.error('TestReachRiskEngine.generateTestSkeleton: step insert failed: ' + e.message);
            }
        }

        // Update the coverage snapshot with skeleton info
        var snapGr = new GlideRecord('x_snc_testreach_coverage_snapshot');
        snapGr.addQuery('artifact_sys_id', artifactSysId);
        snapGr.addQuery('snapshot_type', 'coverage');
        snapGr.query();
        if (snapGr.next()) {
            var skeletonJson = {
                generated: true,
                test_sys_id: testSysId,
                steps: steps,
                ai_generated: stepDescriptions.length > 0
            };
            snapGr.setValue('skeleton_json', JSON.stringify(skeletonJson));
            try {
                snapGr.update();
            } catch (e) {
                gs.error('TestReachRiskEngine.generateTestSkeleton: snapshot update failed: ' + e.message);
            }
        }

        return {
            test_sys_id: testSysId,
            steps: steps
        };
    },

    /**
     * CI/CD gate check. Returns pass/fail against configured threshold.
     *
     * @param {string} appScope - Scope prefix
     * @param {number} threshold - Risk score threshold (0-100, default 60)
     * @returns {object} {pass: boolean, coverage_pct: number, risk_score: number, untested_count: number, threshold: number, recommendation: string}
     */
    checkCIThreshold: function(appScope, threshold) {
        threshold = threshold || 60;

        var riskGr = new GlideRecord('x_snc_testreach_risk_score');
        riskGr.addQuery('app_scope', appScope);
        riskGr.orderByDesc('computed_ts');
        riskGr.setLimit(1);
        riskGr.query();

        if (riskGr.next()) {
            var riskScore = parseInt(riskGr.getValue('risk_score') || 0, 10);
            var coveragePct = parseFloat(riskGr.getValue('coverage_pct') || 0);
            var untestedCount = parseInt(riskGr.getValue('untested_count') || 0, 10);
            var pass = riskScore <= threshold;

            return {
                pass: pass,
                coverage_pct: coveragePct,
                risk_score: riskScore,
                untested_count: untestedCount,
                threshold: threshold,
                recommendation: pass
                    ? 'Coverage gate passed. Risk score ' + riskScore + ' is within threshold ' + threshold + '.'
                    : 'Coverage gate FAILED. Risk score ' + riskScore + ' exceeds threshold ' + threshold + '. Generate test skeletons for ' + untestedCount + ' untested artifacts.'
            };
        }

        // No risk score computed yet — run analysis first
        return {
            pass: false,
            coverage_pct: 0,
            risk_score: 100,
            untested_count: 0,
            threshold: threshold,
            recommendation: 'No risk score available. Run coverage analysis first via POST /execute with action=analyze.'
        };
    },

    /**
     * Aggregated dashboard payload for UI Builder.
     *
     * @param {string} appScope - Scope prefix
     * @returns {object} {heatmap: [], risk: {}, trend: [], gaps: []}
     */
    getDashboardData: function(appScope) {
        // Heatmap data
        var heatmap = [];
        var snapGr = new GlideRecord('x_snc_testreach_coverage_snapshot');
        snapGr.addQuery('app_scope', appScope);
        snapGr.addQuery('snapshot_type', 'coverage');
        snapGr.orderBy('coverage_pct');
        snapGr.query();
        while (snapGr.next()) {
            heatmap.push({
                artifact_name: snapGr.getValue('artifact_name') || '',
                artifact_type: snapGr.getValue('artifact_type') || '',
                artifact_table: snapGr.getValue('artifact_table') || '',
                coverage_pct: parseFloat(snapGr.getValue('coverage_pct') || 0),
                tested_by_count: parseInt(snapGr.getValue('tested_by_count') || 0, 10),
                criticality: parseInt(snapGr.getValue('criticality') || 1, 10)
            });
        }

        // Risk score
        var risk = {};
        var riskGr = new GlideRecord('x_snc_testreach_risk_score');
        riskGr.addQuery('app_scope', appScope);
        riskGr.orderByDesc('computed_ts');
        riskGr.setLimit(1);
        riskGr.query();
        if (riskGr.next()) {
            risk = {
                risk_score: parseInt(riskGr.getValue('risk_score') || 0, 10),
                coverage_pct: parseFloat(riskGr.getValue('coverage_pct') || 0),
                untested_count: parseInt(riskGr.getValue('untested_count') || 0, 10),
                total_artifacts: parseInt(riskGr.getValue('total_artifacts') || 0, 10),
                threshold_pass: riskGr.getValue('threshold_pass') === 'true' || riskGr.getValue('threshold_pass') === true
            };
        }

        // Trend data
        var trend = [];
        var trendGr = new GlideRecord('x_snc_testreach_coverage_snapshot');
        trendGr.addQuery('app_scope', appScope);
        trendGr.addQuery('snapshot_type', 'trend');
        trendGr.orderByDesc('snapshot_ts');
        trendGr.setLimit(12);
        trendGr.query();
        while (trendGr.next()) {
            var trendJson = trendGr.getValue('trend_json') || '{}';
            try {
                var parsed = JSON.parse(trendJson);
                if (parsed.weekly_snapshots) {
                    for (var i = 0; i < parsed.weekly_snapshots.length; i++) {
                        trend.push(parsed.weekly_snapshots[i]);
                    }
                }
            } catch (e) {
                // skip malformed JSON
            }
        }

        // Gap data (zero-coverage artifacts)
        var gaps = [];
        var gapGr = new GlideRecord('x_snc_testreach_coverage_snapshot');
        gapGr.addQuery('app_scope', appScope);
        gapGr.addQuery('snapshot_type', 'gap');
        gapGr.orderByDesc('criticality');
        gapGr.setLimit(20);
        gapGr.query();
        while (gapGr.next()) {
            gaps.push({
                artifact_name: gapGr.getValue('artifact_name') || '',
                artifact_type: gapGr.getValue('artifact_type') || '',
                criticality: parseInt(gapGr.getValue('criticality') || 1, 10)
            });
        }

        return {
            heatmap: heatmap,
            risk: risk,
            trend: trend,
            gaps: gaps,
            summary: {
                app_scope: appScope,
                app_name: this._getAppName(appScope),
                coverage_pct: risk.coverage_pct || 0,
                total_artifacts: risk.total_artifacts || 0,
                untested_count: risk.untested_count || 0,
                tested_count: (risk.total_artifacts || 0) - (risk.untested_count || 0),
                low_coverage_count: 0
            }
        };
    },

    /**
     * Generates human-readable step descriptions for test skeleton.
     * Uses GenAI Controller when available; falls back to template-based descriptions.
     *
     * @param {string} artifactName - Name of the artifact
     * @param {string} artifactType - Type of artifact
     * @param {string} artifactScript - Script content of the artifact
     * @returns {array} [{name: "", description: ""}]
     * @private
     */
    _generateStepDescriptions: function(artifactName, artifactType, artifactScript) {
        var steps = [];

        // Attempt GenAI Controller integration
        try {
            if (typeof sn_generative_ai !== 'undefined' && sn_generative_ai.GenerativeAI) {
                var genAI = new sn_generative_ai.GenerativeAI();
                var prompt = 'Generate 3-5 ATF test step descriptions for testing a ServiceNow ' + artifactType +
                    ' named "' + artifactName + '". The artifact script is:\n\n' + (artifactScript || '(no script available)') +
                    '\n\nReturn each step as: Step N: [name] — [description]. Keep descriptions under 200 characters each.';
                var response = genAI.generate(prompt);
                if (response && response.length > 0) {
                    var lines = response.split('\n');
                    for (var i = 0; i < lines.length; i++) {
                        var line = lines[i].trim();
                        if (line.indexOf('Step') === 0) {
                            var parts = line.split(' — ');
                            var name = parts[0].replace(/^Step \d+: /, '').trim();
                            var desc = parts.length > 1 ? parts[1].trim() : name;
                            steps.push({ name: name, description: desc });
                        }
                    }
                }
            }
        } catch (e) {
            gs.warn('TestReachRiskEngine._generateStepDescriptions: GenAI unavailable, using templates: ' + e.message);
        }

        // Fallback: template-based descriptions
        if (steps.length === 0) {
            if (artifactType === 'business_rule') {
                steps.push({ name: 'Open form and trigger BR', description: 'Open the form on the target table and perform the action that triggers the business rule "' + artifactName + '".' });
                steps.push({ name: 'Verify record update', description: 'Verify that the record was created/updated as expected by the business rule logic.' });
                steps.push({ name: 'Verify field values', description: 'Check that all fields modified by the business rule have the expected values.' });
            } else if (artifactType === 'script_include') {
                steps.push({ name: 'Call Script Include method', description: 'Execute the primary method of Script Include "' + artifactName + '" with valid input parameters.' });
                steps.push({ name: 'Verify return value', description: 'Assert that the return value matches the expected output format and content.' });
                steps.push({ name: 'Test error handling', description: 'Call the method with invalid/null parameters and verify graceful error handling.' });
            } else if (artifactType === 'client_script') {
                steps.push({ name: 'Load form with client script', description: 'Open the form where the client script "' + artifactName + '" is configured to run.' });
                steps.push({ name: 'Trigger client script event', description: 'Perform the UI action (onLoad/onChange/onSubmit) that triggers the client script.' });
                steps.push({ name: 'Verify UI behavior', description: 'Confirm the expected UI behavior (field visibility, value changes, messages).' });
            } else if (artifactType === 'flow') {
                steps.push({ name: 'Trigger flow', description: 'Perform the action or create the record that triggers the flow "' + artifactName + '".' });
                steps.push({ name: 'Verify flow execution', description: 'Check that the flow executed successfully and all steps completed.' });
                steps.push({ name: 'Verify output', description: 'Confirm the flow\'s output records, approvals, or notifications were created correctly.' });
            } else {
                steps.push({ name: 'Execute artifact', description: 'Trigger or execute the ' + artifactType + ' "' + artifactName + '".' });
                steps.push({ name: 'Verify result', description: 'Confirm the expected outcome of the ' + artifactType + ' execution.' });
                steps.push({ name: 'Check edge case', description: 'Test with boundary or edge-case inputs to verify robustness.' });
            }
        }

        return steps;
    },

    /**
     * Builds ATF step config XML for the given artifact type.
     *
     * @param {string} artifactType - Type of artifact
     * @param {string} artifactTable - Table name (for form-based steps)
     * @param {object} stepDesc - {name, description}
     * @returns {string} XML config string
     * @private
     */
    _buildStepConfig: function(artifactType, artifactTable, stepDesc) {
        var config = '<config>';
        config += '<step_type>form</step_type>';
        if (artifactTable) {
            config += '<table>' + artifactTable + '</table>';
        }
        config += '<description>' + this._escapeXml(stepDesc.description) + '</description>';
        config += '<field_values></field_values>';
        config += '</config>';
        return config;
    },

    /**
     * Generates a human-readable recommendation based on risk score.
     *
     * @param {number} riskScore - 0-100 risk score
     * @param {number} untestedCount - Number of untested artifacts
     * @param {string} appScope - Scope prefix
     * @returns {string} Recommendation text
     * @private
     */
    _generateRecommendation: function(riskScore, untestedCount, appScope) {
        if (riskScore >= 80) {
            return 'CRITICAL: ' + untestedCount + ' untested artifacts in ' + appScope + '. Generate test skeletons immediately and add coverage before next upgrade. Risk score ' + riskScore + '/100.';
        } else if (riskScore >= 50) {
            return 'HIGH: ' + untestedCount + ' untested artifacts in ' + appScope + '. Prioritize test creation for high-criticality artifacts. Risk score ' + riskScore + '/100.';
        } else if (riskScore >= 30) {
            return 'MEDIUM: ' + untestedCount + ' untested artifacts in ' + appScope + '. Schedule test creation in current sprint. Risk score ' + riskScore + '/100.';
        } else {
            return 'LOW: Coverage is adequate for ' + appScope + '. Maintain current testing practices. Risk score ' + riskScore + '/100.';
        }
    },

    /**
     * Gets the human-readable app name from sys_app.
     *
     * @param {string} appScope - Scope prefix
     * @returns {string} App name or scope prefix if not found
     * @private
     */
    _getAppName: function(appScope) {
        var appGr = new GlideRecord('sys_app');
        appGr.addQuery('scope', appScope);
        appGr.setLimit(1);
        appGr.query();
        if (appGr.next()) {
            return appGr.getValue('name') || appScope;
        }
        return appScope;
    },

    /**
     * Escapes XML special characters.
     *
     * @param {string} str - Input string
     * @returns {string} XML-safe string
     * @private
     */
    _escapeXml: function(str) {
        if (!str) return '';
        return str.replace(/&/g, '&amp;')
                  .replace(/</g, '&lt;')
                  .replace(/>/g, '&gt;')
                  .replace(/"/g, '&quot;')
                  .replace(/'/g, '&apos;');
    },


    /**
     * Action dispatcher. Single entry point for POST /api/x_snc_testreach/execute.
     *
     * @param {object} body - {action, app_scope, params}
     * @returns {object} {ok: bool, data?: object, error?: string, http_status: number}
     */
    dispatch: function(body) {
        body = body || {};
        var action = body.action;
        var appScope = body.app_scope;
        var params = body.params || {};
        var validActions = ['analyze', 'risk_score', 'upgrade_gap', 'generate_skeleton', 'coverage_check'];

        if (validActions.indexOf(action) === -1) {
            return {
                ok: false,
                error: "Unknown action: '" + action + "'. Valid actions: " + validActions.join(', '),
                http_status: 400
            };
        }
        if (!appScope && action !== 'analyze') {
            return { ok: false, error: 'app_scope is required for action ' + action, http_status: 400 };
        }

        try {
            var coverageEngine = new TestReachCoverageEngine();
            var result;
            switch (action) {
                case 'analyze':
                    var scopeToAnalyze = appScope || '';
                    if (!scopeToAnalyze) {
                        var gr = new GlideRecord('sys_app');
                        gr.addQuery('vendor_prefix', 'x_');
                        gr.addQuery('scope', '!=', 'x_snc_testreach');
                        gr.setLimit(1);
                        gr.query();
                        if (gr.next()) scopeToAnalyze = gr.getValue('scope');
                    }
                    if (!scopeToAnalyze) {
                        return { ok: false, error: 'No app_scope provided and no scoped apps found.', http_status: 400 };
                    }
                    var snapshotSysId = coverageEngine.snapshotCoverage(scopeToAnalyze);
                    result = {
                        snapshot_id: snapshotSysId,
                        app_scope: scopeToAnalyze,
                        message: 'Coverage snapshot written successfully.'
                    };
                    break;
                case 'risk_score':
                    result = this.computeRiskScore(appScope, params.upgrade_target || '');
                    break;
                case 'upgrade_gap':
                    result = { items: this.generateUpgradeGapReport(params.upgrade_target || '') };
                    break;
                case 'generate_skeleton':
                    if (!params.artifact_sys_id) {
                        return { ok: false, error: 'params.artifact_sys_id is required for generate_skeleton.', http_status: 400 };
                    }
                    result = this.generateTestSkeleton(params.artifact_sys_id, params.artifact_type || 'business_rule');
                    break;
                case 'coverage_check':
                    result = this.checkCIThreshold(appScope, params.threshold || 60);
                    break;
            }
            return { ok: true, data: result, http_status: 200 };
        } catch (e) {
            return { ok: false, error: 'Internal error: ' + (e.message || e.toString()), http_status: 500 };
        }
    },

    type: 'TestReachRiskEngine'
};

sys_ws_operation.operation_script:
(function process(request, response) {
  try {
    var body = request.body ? request.body.data : {};
    if (typeof body === 'string') {
      try { body = JSON.parse(body); } catch (e) { body = {}; }
    }
    if (!body) body = {};
    var engine = new x_snc_testreach.TestReachRiskEngine();
    var result = engine.dispatch(body);
    if (!result.ok) {
      response.setStatus(result.http_status || 400);
    } else {
      response.setStatus(result.http_status || 200);
    }
    response.setContentType('application/json');
    var payload = result.ok ? { ok: true, data: result.data } : { ok: false, error: result.error };
    response.getStreamWriter().writeString(JSON.stringify(payload));
  } catch (e) {
    response.setStatus(500);
    response.setContentType('application/json');
    response.getStreamWriter().writeString(JSON.stringify({
      ok: false,
      error: 'Unhandled exception: ' + (e.message || e.toString())
    }));
  }
})(request, response);

(function process(request, response) {
  try {
    var params = request.queryParams || {};
    var appScope = params.app_scope;
    if (!appScope) {
      response.setStatus(400);
      response.setContentType('application/json');
      response.getStreamWriter().writeString(JSON.stringify({
        ok: false,
        error: 'app_scope query parameter is required'
      }));
      return;
    }
    var includeTrend = (params.include_trend === 'true' || params.include_trend === true);
    var includeGaps = (params.include_gaps === 'true' || params.include_gaps === true);
    var upgradeTarget = params.upgrade_target || '';
    var engine = new x_snc_testreach.TestReachRiskEngine();
    var dashboard = engine.getDashboardData(appScope);
    var data = {
      app_scope: appScope,
      app_name: dashboard.summary.app_name,
      coverage_pct: dashboard.summary.coverage_pct,
      total_artifacts: dashboard.summary.total_artifacts,
      tested_count: dashboard.summary.tested_count,
      untested_count: dashboard.summary.untested_count,
      risk_score: dashboard.risk ? dashboard.risk.risk_score : 0,
      last_analyzed: dashboard.risk ? dashboard.risk.computed_ts : ''
    };
    if (includeTrend) data.trend = dashboard.trend;
    if (includeGaps) data.top_gaps = dashboard.gaps;
    response.setStatus(200);
    response.setContentType('application/json');
    response.getStreamWriter().writeString(JSON.stringify({ ok: true, data: data }));
  } catch (e) {
    response.setStatus(500);
    response.setContentType('application/json');
    response.getStreamWriter().writeString(JSON.stringify({
      ok: false,
      error: 'Unhandled exception: ' + (e.message || e.toString())
    }));
  }
})(request, response);

sys_script.script:
(function executeRule(current, previous) {
  var score = parseInt(current.getValue('risk_score'), 10);
  if (isNaN(score) || score < 0 || score > 100) {
    gs.addErrorMessage('TestReach: risk_score must be between 0 and 100.');
    current.setAbortAction(true);
    return;
  }
  if (!current.getValue('app_scope')) {
    gs.addErrorMessage('TestReach: app_scope is required.');
    current.setAbortAction(true);
    return;
  }
  var untested = parseInt(current.getValue('untested_count'), 10) || 0;
  var lowCov   = parseInt(current.getValue('low_coverage_count'), 10) || 0;
  var total    = parseInt(current.getValue('total_artifacts'), 10) || 0;
  if (total < 0 || untested < 0 || lowCov < 0 || untested > total) {
    gs.addErrorMessage('TestReach: artifact counts are inconsistent (untested_count cannot exceed total_artifacts).');
    current.setAbortAction(true);
    return;
  }
  current.setValue('threshold_pass', score <= 50);
  if (!current.getValue('computed_ts')) {
    current.setValue('computed_ts', new GlideDateTime());
  }
})(current, previous);

(function executeRule(current, previous) {
  var type = current.getValue('snapshot_type');
  var validTypes = ['coverage', 'trend', 'gap'];
  if (validTypes.indexOf(type) === -1) {
    gs.addErrorMessage("TestReach: snapshot_type must be one of: " + validTypes.join(', '));
    current.setAbortAction(true);
    return;
  }
  if (!current.getValue('app_scope')) {
    gs.addErrorMessage('TestReach: app_scope is required on coverage snapshot rows.');
    current.setAbortAction(true);
    return;
  }
  if (!current.getValue('artifact_sys_id')) {
    gs.addErrorMessage('TestReach: artifact_sys_id is required on coverage snapshot rows.');
    current.setAbortAction(true);
    return;
  }
  var pct = parseFloat(current.getValue('coverage_pct'));
  if (isNaN(pct) || pct < 0 || pct > 100) {
    current.setValue('coverage_pct', 0);
  }
  if (!current.getValue('snapshot_ts')) {
    current.setValue('snapshot_ts', new GlideDateTime());
  }
  var crit = parseInt(current.getValue('criticality'), 10);
  if (isNaN(crit) || crit < 1) current.setValue('criticality', 1);
  if (crit > 5) current.setValue('criticality', 5);
})(current, previous);

sysauto_script.script:
(function() {
  var engine = new x_snc_testreach.TestReachCoverageEngine();
  var scopeGr = new GlideRecord('sys_app');
  scopeGr.addQuery('vendor_prefix', 'x_');
  scopeGr.addQuery('scope', '!=', 'global');
  scopeGr.addQuery('scope', '!=', 'x_snc_testreach');
  scopeGr.query();
  while (scopeGr.next()) {
    var scope = scopeGr.getValue('scope');
    if (!scope) continue;
    try {
      var result = engine.snapshotCoverage(scope);
      gs.log('TestReach: nightly scan for ' + scope + ' complete. coverage=' +
        result.coverage_pct + '% tested=' + result.tested_count +
        ' untested=' + result.untested_count);
    } catch (e) {
      gs.logError('TestReach: nightly scan failed for ' + scope + ': ' + e.message, 'TestReach');
    }
  }
})();

(function() {
  var engine = new x_snc_testreach.TestReachRiskEngine();
  var scopeGr = new GlideRecord('sys_app');
  scopeGr.addQuery('vendor_prefix', 'x_');
  scopeGr.addQuery('scope', '!=', 'global');
  scopeGr.addQuery('scope', '!=', 'x_snc_testreach');
  scopeGr.query();
  while (scopeGr.next()) {
    var scope = scopeGr.getValue('scope');
    if (!scope) continue;
    try {
      var risk = engine.computeRiskScore(scope, '');
      gs.log('TestReach: weekly risk refresh for ' + scope + ' risk_score=' + risk.risk_score);
    } catch (e) {
      gs.logError('TestReach: weekly risk refresh failed for ' + scope + ': ' + e.message, 'TestReach');
    }
  }
})();

sp_widget.client_script:
api.controller=function() {
  var c = this;
  c.data = { ok: false, summary: null, trend: [], topGaps: [] };
  c.serverAction = 'load';
};

sp_widget.script_server:
(function() {
  data.appScope = input.app_scope || $sp.getParameter('app_scope') || '';
  if (!data.appScope) {
    data.ok = false;
    return;
  }
  try {
    var engine = new x_snc_testreach.TestReachRiskEngine();
    var dashboard = engine.getDashboardData(data.appScope);
    data.ok = true;
    data.summary = dashboard.summary;
    data.risk = dashboard.risk;
    data.trend = dashboard.trend;
    data.topGaps = dashboard.gaps.slice(0, 10);
  } catch (e) {
    data.ok = false;
    data.error = e.message;
  }
})();
